(window["webpackJsonp"]=window["webpackJsonp"]||[]).push([["sintesis"],{"15a3":function(a,e,s){"use strict";s.r(e);var i=function(){var a=this,e=a._self._c;return e("div",{staticClass:"curso-main-container pb-3"},[e("BannerInterno",{attrs:{icono:"fas fa-sitemap",titulo:"Síntesis"}}),e("div",{staticClass:"container tarjeta tarjeta--blanca p-4 p-md-5"},[e("p",[a._v("La comprensión y aplicación de los fundamentos para el establecimiento de cultivos en agricultura urbana constituye un proceso esencial para desarrollar sistemas productivos eficientes, sostenibles y adaptados a entornos con limitaciones de espacio. La adecuada preparación de herramientas, insumos y condiciones de siembra permite optimizar el uso de recursos, garantizar la sanidad del cultivo y favorecer un desarrollo vegetal adecuado desde las etapas iniciales. Este componente formativo articula el manejo técnico de la siembra con la comprensión de las condiciones edafoclimáticas, reconociendo que la interacción entre sustrato, clima y características del cultivo determina el éxito productivo.")]),e("p",[a._v("La implementación de prácticas adecuadas en el manejo de agroinsumos, la definición de densidades y distancias de siembra, y el control de factores como riego, ventilación y exposición solar permiten mejorar la eficiencia productiva y reducir riesgos asociados a plagas, enfermedades y condiciones ambientales adversas. Estas prácticas, fundamentadas en criterios técnicos rigurosos, promueven el uso racional de recursos y la minimización de impactos ambientales, consolidando un enfoque de agricultura urbana responsable y sostenible.")]),e("p",[a._v("Finalmente, este componente formativo desarrolla competencias técnicas que permiten al aprendiz planificar, ejecutar y evaluar procesos de siembra en contextos urbanos, fortaleciendo su capacidad para implementar sistemas productivos sostenibles. De esta manera, se contribuye a la producción de alimentos en espacios urbanos, el aprovechamiento eficiente de recursos disponibles y la adopción de prácticas agrícolas responsables adaptadas a las dinámicas actuales del territorio.")]),e("div",{staticClass:"row justify-content-center"},[a._m(0),e("div",{staticClass:"col-auto"},[e("a",{staticClass:"anexo mb-5",attrs:{href:a.obtenerLink("/downloads/Sintesis.pdf"),target:"_blank"}},[a._m(1),a._m(2)])])])])],1)},n=[function(){var a=this,e=a._self._c;return e("div",{staticClass:"col-lg-11 mb-5 bgs p-4 brad"},[e("figure",[e("img",{attrs:{src:s("cc8e"),alt:"Diagrama de flujo titulado “Fundamentos para la siembra y establecimiento de cultivos urbanos”. Del título principal se desprenden dos ramas. En la rama izquierda aparece el subtítulo “Fundamentos para la preparación de la siembra”, seguido en secuencia por los temas: Equipos y herramientas de siembra, Insumos agrícolas, Agroinsumos, Fundamentos de la siembra y Condiciones edafoclimáticas. En la rama derecha aparece el subtítulo “Establecimiento del cultivo en contenedores”, seguido de Siembra en agricultura urbana, con los subtemas técnicas y profundidad, densidad y distancia; luego Línea de siembra, con los subtemas técnicas de trazado, técnicas de marcación, criterios de orientación y ventilación; y finalmente Relación suelo-clima-cultivo, con los subtemas aplicación en agricultura urbana, control de sombra, manejo del riego y control de ventilación."}})])])},function(){var a=this,e=a._self._c;return e("div",{staticClass:"anexo__icono"},[e("img",{attrs:{src:s("abd8")}})])},function(){var a=this,e=a._self._c;return e("div",{staticClass:"anexo__texto"},[e("p",[a._v("Anexo. Síntesis")])])}],o={name:"Sintesis",data:()=>({}),mounted(){this.$nextTick(()=>{this.$aosRefresh()})},updated(){this.$aosRefresh()}},t=o,c=s("2877"),r=Object(c["a"])(t,i,n,!1,null,null,null);e["default"]=r.exports},abd8:function(a,e,s){a.exports=s.p+"img/icono-pdf.82f139cb.svg"},cc8e:function(a,e,s){a.exports=s.p+"img/sintesis.dacb6910.svg"}}]);
